values
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-556', 'O principio da legalidade penal, no direito brasileiro, veda:', '["A retroatividade benéfica.","A aplicacao da lei mais benéfica.","A tipicidade.","A culpabilidade.","A analogia em desfavor do reu."]'::jsonb, 4, 'O principio da legalidade penal veda a analogia em desfavor do reu.', 'easy', 'Principio da legalidade penal', 'multiple_choice', 'published', 5625, 'CEBRASPE', 'Carreiras policiais'),
